## 파멸의 돌격이 밀어낼 방향을 바꾼다
**헤카림의 E는 이동 속도가 오르며 다음 공격으로 대상을 밀어내므로, 일직선으로 도망치면 적진 쪽으로 배달되기 쉽다.**[* [헤카림 챔피언 정보](https://lol.inven.co.kr/dataninfo/champion/detail.php?code=96)] `E` 소리가 들리면 옆으로 빠져 뒤를 잡지 못하게 하고, 포탑 쪽 벽을 등진다. 진입 전 가속 구간에 둔화를 써도 한 번에 멈출 것이라 기대하지 않는다.

## 회오리 베기 중첩이 없는 순간을 고른다
**헤카림은 Q를 연속 적중하면 다음 사용이 빨라지고 피해가 커진다.** 캠프를 막 정리한 헤카림은 중첩을 들고 올 수 있으므로 표시와 시간을 확인한다. 중첩이 끊긴 뒤 짧게 싸우고, 여러 명이 가까이 서서 광역 피해를 모두 맞지 않는다.

## 공포의 망령 범위에서는 피해를 나누지 않는다
**`W`가 켜진 동안 주변 적이 받는 피해 일부로 헤카림이 회복하고 방어 능력도 오른다.** 효과가 보이면 화력이 부족한 교전을 길게 끌지 말고 범위 밖으로 빠진다. 반드시 잡아야 한다면 회복 감소보다 확실한 제어와 집중 피해로 지속시간을 주지 않는다.

## 그림자의 맹습이 끝난 위치를 노린다
**궁 돌진 자체를 멈추기 어렵지만 공포는 헤카림의 착지 위치에서 퍼진다.** 정면으로 뭉치지 말고 옆 간격을 벌려 한 번에 진형이 무너지지 않게 한다. 착지와 공포가 끝난 직후 퇴로에 제어를 겹치면, 이미 E를 쓴 헤카림의 이탈을 막을 수 있다.

## 솔랭에서 바로 쓰는 정글 운영

## 초반 동선과 첫 개입
**무조건 정해진 동선을 외우기보다, 갱이 실패해도 다음 행동이 남는 쪽을 고른다.**[* [MOBAFire 헤카림 정글 가이드](https://www.mobafire.com/league-of-legends/build/the-grave-calls-hecarim-jungle-guide-season-16-updated-patch-16-15-653186)] 헤카림은 풀캠을 반복하며 같은 리젠 순서로 도는 경우가 많아 캠프 하나에 깊은 와드를 두면 다음 동선까지 읽기 쉽다. 갱을 한 번 피했다면 그쪽 캠프 리젠 전에 역갱을 준비하거나 반대편을 턴다. 라인만 보는 얕은 와드는 빠른 이속 때문에 늦을 수 있다.

## 맞딜과 핵심 스킬쿨
캠프에서 바로 나온 헤카림은 `Q` 중첩을 들고 올 수 있으니 강가에서 바로 맞딜하지 않는다. 중첩이 끊긴 뒤 싸우고, `E`로 달려오면 뒤로만 빼지 말고 직각으로 움직여 밀릴 방향을 바꾼다. 포탑 쪽 벽을 등지면 적진으로 배달되는 거리를 줄일 수 있다.

## 카정과 상대 정글 추적
`W`가 켜진 동안 애매한 딜을 오래 나눠 넣으면 헤카림이 계속 버틴다. 범위 밖으로 잠깐 빠지거나 확정 CC와 점사로 지속시간을 주지 않는다. 궁 돌진 자체보다 착지 위치의 공포 방향을 보고 좌우 간격을 벌린다.

## 용·전령 앞 판단
오브젝트 앞 좁은 입구에 뭉치면 궁 한 번에 정글러와 딜러가 함께 밀린다. 들어오는 방향을 와드로 먼저 밝히고 구덩이 안팎으로 역할을 나눈다. 헤카림이 궁과 `E`를 모두 진입에 쓰면 돌아갈 스킬이 적으니 착지 뒤 퇴로에 CC를 둔다.

## 한타에서 맡을 역할
한타에서는 딜러가 뒤로만 일직선 도망치지 말고 옆으로 빠져 헤카림의 가속과 공포 각을 틀어야 한다. 앞라인은 헤카림 본체를 쫓기보다 뒤따르는 적의 길을 막는다. `W`가 끝난 뒤 같은 대상을 점사해 회복 구간을 다시 주지 않는다.

## 말렸을 때 복구법
헤카림이 성장했으면 정글 안에서 추격전을 열지 않는다. 라인 웨이브를 먼저 정리해 달릴 공간을 줄이고, 캠프 리젠 위치에 미리 모여 한 번에 밀어낸다. 궁이 반대편 갱에 빠지면 가까운 오브젝트를 바로 시작해 스킬쿨을 맵 이득으로 바꾼다.

